def transform_integers_to_hex(file_path: str) -> str:
    with open(file_path, 'rb') as file:
        source_code_bytes = file.read()

    tokens = list(tokenize.tokenize(BytesIO(source_code_bytes).readline))

    for token in tokens:
        if token.type == tokenize.NUMBER and token.string.isdigit():
            token.string = hex(int(token.string))
        elif token.type == tokenize.NUMBER and token.string.startswith('-'):
            number_str = token.string[1:]
            if number_str.isdigit():
                token.string = '-0x' + hex(int(number_str))[2:]

    modified_source_code = tokenize.untokenize(tokens).decode('utf-8')
    return modified_source_code

